cuda_source = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>

#ifndef __HALF2_TO_UI__
#define __HALF2_TO_UI(x) __hiloint2float(x.x, x.y)
#endif

// --------------------------------------------------------------------
// Kernel: C = A (M x K)  *  B^T (K x N)   where B is stored as (N x K)
// --------------------------------------------------------------------
extern "C"
__global__ void matmul_fp16_kernel(const half* __restrict__ A,
                                   const half* __restrict__ B,
                                   half* __restrict__ C,
                                   int M, int K, int N) {
    // Tile size
    const int TILE = 16;

    // Thread indices within the block
    int tx = threadIdx.x; // column within tile
    int ty = threadIdx.y; // row within tile

    // Global row and column this thread computes
    int row = blockIdx.y * TILE + ty;
    int col = blockIdx.x * TILE + tx;

    // Shared memory tiles
    __shared__ half As[TILE][TILE];
    __shared__ half Bs[TILE][TILE];

    float acc = 0.0f; // accumulation in FP32

    // Loop over K dimension tiles
    int numTiles = (K + TILE - 1) / TILE;
    for (int t = 0; t < numTiles; ++t) {
        // Load A tile
        int aRow = row;
        int aCol = t * TILE + tx;
        if (aRow < M && aCol < K) {
            As[ty][tx] = A[aRow * K + aCol];
        } else {
            As[ty][tx] = __float2half(0.0f);
        }

        // Load B tile (remember B is (N, K); we need B^T)
        int bOrigRow = col;          // n index in original B (N dim)
        int bOrigCol = t * TILE + ty; // k index
        if (bOrigRow < N && bOrigCol < K) {
            // B_T[k, n] = B[n, k]
            Bs[ty][tx] = B[bOrigRow * K + bOrigCol];
        } else {
            Bs[ty][tx] = __float2half(0.0f);
        }

        __syncthreads();

        // Compute partial product for this tile
        #pragma unroll
        for (int i = 0; i < TILE; ++i) {
            acc += __half2float(As[ty][i]) * __half2float(Bs[i][tx]);
        }

        __syncthreads();
    }

    // Write result
    if (row < M && col < N) {
        C[row * N + col] = __float2half(acc);
    }
}

// --------------------------------------------------------------------
// C++ launcher
// --------------------------------------------------------------------
void matmul_fp16_launcher(at::Tensor A, at::Tensor B, at::Tensor C) {
    const int M = A.size(0);
    const int K = A.size(1);
    const int N = B.size(0); // B shape is (N, K)

    const dim3 block(16, 16);
    const dim3 grid((N + 15) / 16, (M + 15) / 16);

    const half* a_ptr = reinterpret_cast<const half*>(A.data_ptr<at::Half>());
    const half* b_ptr = reinterpret_cast<const half*>(B.data_ptr<at::Half>());
    half* c_ptr = reinterpret_cast<half*>(C.data_ptr<at::Half>());

    // Launch kernel on the current CUDA stream
    AT_CUDA_CHECK(cudaGetLastError());
    matmul_fp16_kernel<<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
        a_ptr, b_ptr, c_ptr, M, K, N);
    AT_CUDA_CHECK(cudaGetLastError());
}
'''

# --------------------------------------------------------------------
# Load the extension
# --------------------------------------------------------------------
matmul_ext = load_inline(name='matmul_fp16_ext',
                         cpp_sources='',
                         cuda_sources=cuda_source,
                         functions=['matmul_fp16_launcher'],
                         verbose=False)

# --------------------------------------------------------------------
# Model definition using the custom kernel
# --------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model.
    Performs C = A @ B.T with fp16 tensors using a custom CUDA kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Ensure proper dtype and device
        if A.dtype != torch.float16 or B.dtype != torch.float16:
            raise TypeError("ModelNew expects fp16 inputs")
        if not A.is_cuda or not B.is_cuda:
            raise RuntimeError("ModelNew expects CUDA tensors")
        if A.shape[1] != B.shape[1]:
            raise RuntimeError(f"Incompatible inner dimensions: A:{A.shape}, B:{B.shape}")

        M, K = A.shape
        N, Kb = B.shape
        assert K == Kb

        # Allocate output
        C = torch.empty((M, N), dtype=torch.float16, device=A.device)

        # Call the kernel
        matmul_ext.matmul_fp16_launcher(A, B, C)

        return C

# --------------------------------------------------------------------
# Helper functions matching the original script's API
# --------------------------------------------------------------------
def get_inputs():
    M = 1024 * 2
    K = 4096 * 2
    N = 2048 * 2
    A = torch.rand(M, K, dtype=torch.float16, device='cuda')
    B = torch.rand(N, K, dtype=torch.float16, device='cuda')
    return [A, B]

def get_init_inputs():
    return []  # No special init needed

# Example sanity check (can be removed in production)
if __name__ == "__main__":
    A, B = get_inputs()
    model = ModelNew().cuda()
    C = model(A, B)
    # Verify against torch.matmul for correctness (optional)
    ref = torch.matmul(A, B.t())
    max_err = (C.float() - ref).abs().max()
    print(f"Max absolute error vs torch.matmul: {max_err.item()}")
